type State={user:{id:string;email:string;name:string;role:string};documents:Doc[];products:Product[];suppliers:{id:string;name:string}[];counts:Record<string,number>;pagination?:{products:number};productCategories?:string[];categoriesTruncated?:boolean;members:{email:string;role:string;active:boolean|number}[]};
