async function offerRead(d:Doc,attachments:Attachment[]){if(aiConfig.hasKey&&attachments.every(f=>f.type==='application/pdf'||f.type.startsWith('image/'))){setCloudConsent(false);setPendingCloud({document:d,attachments,model:aiConfig.model});setStep(2);}else await autoExtract(d,attachments);}
